  <script>
    const products = {
      tomato: { qty: 1, unit: 8.50, priceEl: document.getElementById('tomato-price'), qtyEl: document.getElementById('tomato-qty') },
      milk: { qty: 1, unit: 11.00, priceEl: document.getElementById('milk-price'), qtyEl: document.getElementById('milk-qty') },
      eggs: { qty: 1, unit: 14.25, priceEl: document.getElementById('eggs-price'), qtyEl: document.getElementById('eggs-qty') }
    };

    const arabicNumbers = ['٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩'];
    const toArabicNumber = value => String(value).replace(/\d/g, digit => arabicNumbers[digit]);
    const formatPrice = value => toArabicNumber(value.toFixed(2).replace('.', '٫'));

    let discount = 0;

    function calculateTotals() {
      const subtotal = Object.values(products).reduce((sum, item) => sum + item.unit * item.qty, 0);
      const delivery = 5;
      const taxable = Math.max(0, subtotal - discount);
      const vat = taxable * 0.05;
      const total = taxable + delivery + vat;

      document.getElementById('subtotal').textContent = `${formatPrice(subtotal)} درهم`;
      document.getElementById('vat').textContent = `${formatPrice(vat)} درهم`;
      document.getElementById('total').textContent = `${formatPrice(total)} درهم`;

      if (discount > 0) {
        document.getElementById('discount-row').hidden = false;
        document.getElementById('discount').textContent = `− ${formatPrice(discount)} درهم`;
      }
    }

    function updateQuantity(key, step) {
      const product = products[key];
      product.qty = Math.max(1, Math.min(20, product.qty + step));
      product.qtyEl.textContent = toArabicNumber(product.qty);
      product.priceEl.textContent = formatPrice(product.unit * product.qty);
      calculateTotals();
    }

    document.querySelectorAll('[data-item]').forEach(button => {
      button.addEventListener('click', () => {
        updateQuantity(button.dataset.item, Number(button.dataset.step));
      });
    });

    document.querySelectorAll('.remove-button').forEach(button => {
      button.addEventListener('click', () => {
        const item = button.closest('.cart-item');
        item.style.opacity = '.35';
        item.style.pointerEvents = 'none';
        showToast('تم حذف المنتج من السلة');
      });
    });

    document.getElementById('apply-promo').addEventListener('click', () => {
      const input = document.getElementById('promo');
      const message = document.getElementById('promo-message');
      if (input.value.trim() === '') {
        message.textContent = 'أدخل رمز الخصم أولًا';
        message.style.color = '#c54b4b';
        message.style.display = 'block';
        return;
      }
      discount = 3;
      message.textContent = '✓ تم تطبيق خصم ٣٫٠٠ درهم';
      message.style.color = '#0c7955';
      message.style.display = 'block';
      calculateTotals();
    });

    document.getElementById('place-order').addEventListener('click', () => {
      showToast('تم إرسال طلبك بنجاح');
      const button = document.getElementById('place-order');
      button.innerHTML = '✓ تم تأكيد الطلب';
      setTimeout(() => {
        button.innerHTML = '<svg viewBox="0 0 24 24" fill="none"><path d="M5 7h14l-1 12H6L5 7z" stroke="currentColor" stroke-width="1.9"/><path d="M9 9V6a3 3 0 016 0v3" stroke="currentColor" stroke-width="1.9"/></svg> تأكيد الطلب';
      }, 1800);
    });

    function showToast(message) {
      const toast = document.getElementById('toast');
      toast.textContent = message;
      toast.classList.add('show');
      clearTimeout(window.toastTimer);
      window.toastTimer = setTimeout(() => toast.classList.remove('show'), 2200);
    }

    calculateTotals();
  </script>
</body>
</html>
